describe('Login Form CAPTCHA Trigger', () => {
  beforeEach(() => {
    cy.visit('/login');
  });

  it('should display CAPTCHA after 3 failed login attempts', () => {
    // First failed attempt
    cy.get('[data-testid="email-input"]').type('user@example.com');
    cy.get('[data-testid="password-input"]').type('wrongpassword123');
    cy.get('[data-testid="login-button"]').click();
    cy.get('[data-testid="error-message"]').should('be.visible').should('contain', 'Invalid credentials');

    // Second failed attempt
    cy.get('[data-testid="password-input"]').clear().type('wrongpassword123');
    cy.get('[data-testid="login-button"]').click();
    cy.get('[data-testid="error-message"]').should('be.visible').should('contain', 'Invalid credentials');

    // Third failed attempt - CAPTCHA should appear
    cy.get('[data-testid="password-input"]').clear().type('wrongpassword123');
    cy.get('[data-testid="login-button"]').click();
    cy.get('[data-testid="captcha-container"]').should('be.visible');
    cy.get('[data-testid="captcha-prompt"]').should('contain', 'Please complete the CAPTCHA');
    cy.get('[data-testid="login-button"]').should('be.disabled');
  });

  it('should allow login with valid credentials before CAPTCHA is triggered', () => {
    // First attempt - valid credentials
    cy.get('[data-testid="email-input"]').type('user@example.com');
    cy.get('[data-testid="password-input"]').type('correctpassword123');
    cy.get('[data-testid="login-button"]').click();
    cy.get('[data-testid="login-success-message"]').should('be.visible').should('contain', 'Login successful');
    cy.get('[data-testid="captcha-container"]').should('not.exist');
  });
});
